#!/usr/bin/env bash
set -euo pipefail
mkdir -p /opt/zadachnik /var/lib/zadachnik/files
cat >/opt/zadachnik/server.js <<'NODE'
const http=require('http'),fs=require('fs'),path=require('path');const{execFileSync}=require('child_process');const DB='/var/lib/zadachnik/zadachnik.db',PORT=3017,FILE_DIR='/var/lib/zadachnik/files';fs.mkdirSync(FILE_DIR,{recursive:true});const sh=q=>execFileSync('sqlite3',['-json',DB,q],{encoding:'utf8'}),run=q=>execFileSync('sqlite3',[DB,q]),esc=v=>String(v??'').replaceAll("'","''");run(`CREATE TABLE IF NOT EXISTS folders(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);`);run(`CREATE TABLE IF NOT EXISTS tasks(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,description TEXT DEFAULT '',folder_id INTEGER,urgency TEXT DEFAULT 'not_urgent',importance TEXT DEFAULT 'not_important',start_at TEXT,due_at TEXT,is_completed INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);`);run(`CREATE TABLE IF NOT EXISTS task_files(id INTEGER PRIMARY KEY AUTOINCREMENT,task_id INTEGER NOT NULL,file_name TEXT NOT NULL,file_type TEXT DEFAULT '',file_path TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);`);for(const c of ['description','urgency','importance','start_at','is_completed','updated_at']){try{run(`ALTER TABLE tasks ADD COLUMN ${c} TEXT DEFAULT ''`)}catch{}}
const html=`<!doctype html><html lang=ru><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>Zadachnik</title><style>:root{--bg:#f5f5f7;--panel:rgba(255,255,255,.86);--line:rgba(15,23,42,.08);--text:#0f172a;--muted:#64748b;--red:#ef4444;--green:#10b981;--yellow:#f59e0b;--shadow:0 24px 70px rgba(15,23,42,.10)}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at top left,#fff 0,#f5f5f7 40%,#eef1f6 100%);color:var(--text);font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif}.app{display:grid;grid-template-columns:300px 1fr;min-height:100vh}.side{background:rgba(255,255,255,.72);border-right:1px solid var(--line);padding:26px 22px;backdrop-filter:blur(24px);position:sticky;top:0;height:100vh}.logo{font-size:28px;font-weight:900;letter-spacing:-.06em}.muted{color:var(--muted);line-height:1.35}.main{padding:44px 34px}.main h1{font-size:46px;margin:0 0 12px;letter-spacing:-.07em}.card,.panel{background:var(--panel);border:1px solid rgba(255,255,255,.9);border-radius:34px;padding:24px;box-shadow:var(--shadow);backdrop-filter:blur(20px)}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:28px 0}.num{font-size:48px;font-weight:900;letter-spacing:-.08em}.red{color:#dc2626}.green{color:#059669}.yellow{color:#d97706}.input,select,textarea{border:1px solid rgba(15,23,42,.10);border-radius:18px;padding:0 16px;font-size:15px;background:rgba(255,255,255,.95);outline:none}.input,select{height:52px}textarea{padding-top:14px;min-height:110px;resize:vertical}.btn{border:0;border-radius:18px;background:#111827;color:white;padding:15px 18px;font-weight:800;cursor:pointer;box-shadow:0 12px 28px rgba(17,24,39,.16)}.ghost{background:#f8fafc;color:#0f172a;box-shadow:none;border:1px solid #e5e7eb}.task{border-left:5px solid #cbd5e1;background:#fff;border-radius:22px;margin:12px 0;padding:16px 18px;border:1px solid #f1f5f9;box-shadow:0 10px 24px rgba(15,23,42,.05);cursor:pointer}.task.over{border-left-color:var(--red)}.task.today{border-left-color:var(--green)}.task.tomorrow{border-left-color:var(--yellow)}.row{display:flex;gap:12px;flex-wrap:wrap;align-items:center}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.views{display:grid;grid-template-columns:repeat(5,1fr);gap:14px;margin-top:15px}.view{background:linear-gradient(180deg,#fff,#f8fafc);border:1px solid #eef2f7;border-radius:24px;padding:20px;min-height:120px;font-weight:800}.modal{position:fixed;inset:0;background:rgba(15,23,42,.42);display:none;align-items:center;justify-content:center;padding:20px}.modal.open{display:flex}.box{width:min(760px,100%);max-height:90vh;overflow:auto;background:#fff;border-radius:34px;padding:24px;box-shadow:0 30px 90px rgba(0,0,0,.25)}.badge{display:inline-flex;padding:6px 10px;border-radius:999px;background:#f1f5f9;color:#475569;font-size:12px;font-weight:700}#foldersList p{background:#f8fafc;border:1px solid #eef2f7;padding:12px 14px;border-radius:16px;margin:8px 0}@media(max-width:900px){.app{grid-template-columns:1fr}.side{height:auto;position:relative}.cards,.views,.grid{grid-template-columns:1fr}.main{padding:22px}.main h1{font-size:34px}}</style></head><body><div class=app><aside class=side><div class=logo>Zadachnik</div><p class=muted>Серверная версия: задачи, папки и файлы сохраняются на VDS.</p><button class=btn onclick=openTask()>+ Создать задачу</button><h3>Папки</h3><div id=foldersList></div><div class=row><input id=folderName class=input placeholder="Новая папка"><button class="btn ghost" onclick=addFolder()>+</button></div></aside><main class=main><h1>Главный дашборд</h1><p class=muted>Сначала просроченные, потом сегодня, завтра и без даты.</p><div class=cards><div class=card><span class=muted>Просрочено</span><div id=cOver class="num red">0</div></div><div class=card><span class=muted>Сегодня</span><div id=cToday class="num green">0</div></div><div class=card><span class=muted>Завтра</span><div id=cTomorrow class="num yellow">0</div></div><div class=card><span class=muted>Всего</span><div id=cAll class=num>0</div></div></div><section class=panel><div class=row style="justify-content:space-between"><h2>Задачи</h2><input id=search class=input placeholder=Поиск oninput=render()></div><div id=tasksList></div></section><section class=panel style="margin-top:18px"><h2>Виды внутри папки</h2><div class=views><div class=view>Список</div><div class=view>Канбан</div><div class=view>Дерево</div><div class=view>Гант</div><div class=view>Матрица</div></div></section></main></div><div id=modal class=modal><div class=box><h2>Карточка задачи</h2><div class=grid><input id=tTitle class=input placeholder="Название *"><select id=tFolder></select><select id=tUrgency><option value=not_urgent>Не срочно</option><option value=urgent>Срочно</option></select><select id=tImportance><option value=not_important>Не важно</option><option value=important>Важно</option></select><input id=tStart class=input type=datetime-local><input id=tDue class=input type=datetime-local></div><textarea id=tDesc style="width:100%;margin-top:12px" placeholder=Описание></textarea><div id=filesBlock style="margin-top:16px;padding:16px;border:1px dashed #cbd5e1;border-radius:22px;background:#f8fafc"><b>Вложения</b><p class=muted>Клик по названию откроет файл. Картинки и PDF откроются в браузере, Word/Excel скачиваются.</p><div id=filesList><p class=muted>Сначала сохраните задачу, потом прикрепляйте файлы.</p></div><div class=row><input id=fileInput type=file class=input><button class="btn ghost" onclick=uploadFile()>Загрузить файл</button></div></div><div class=row style="justify-content:flex-end;margin-top:16px"><button class="btn ghost" onclick=closeTask()>Закрыть</button><button class=btn onclick=saveTask()>Сохранить</button></div></div></div><script>let folders=[],tasks=[],editing=null;const api=p=>'/zadachnik/api'+p;async function load(){folders=await fetch(api('/folders')).then(r=>r.json());tasks=await fetch(api('/tasks')).then(r=>r.json());render()}function day(v){if(!v)return'none';const d=new Date(v),a=new Date();a.setHours(0,0,0,0);const b=new Date(a);b.setDate(a.getDate()+1);const c=new Date(a);c.setDate(a.getDate()+2);if(d<a)return'over';if(d>=a&&d<b)return'today';if(d>=b&&d<c)return'tomorrow';return'future'}function render(){const q=(search?.value||'').toLowerCase();tFolder.innerHTML='<option value="">Без папки</option>'+folders.map(f=>'<option value="'+f.id+'">'+f.name+'</option>').join('');foldersList.innerHTML=folders.map(f=>'<p>📁 '+f.name+'</p>').join('')||'<p class=muted>Папок пока нет</p>';let list=tasks.filter(t=>(t.title||'').toLowerCase().includes(q));cOver.textContent=tasks.filter(t=>day(t.due_at)=='over').length;cToday.textContent=tasks.filter(t=>day(t.due_at)=='today').length;cTomorrow.textContent=tasks.filter(t=>day(t.due_at)=='tomorrow').length;cAll.textContent=tasks.length;tasksList.innerHTML=list.map(t=>'<div class="task '+day(t.due_at)+'" onclick="openTask('+t.id+')"><b>'+t.title+'</b><br><span class=muted>'+(t.due_at||'Без даты')+' · '+(t.folder_name||'Без папки')+'</span><br><span class=badge>'+(t.urgency=='urgent'?'Срочно':'Не срочно')+' · '+(t.importance=='important'?'Важно':'Не важно')+'</span></div>').join('')||'<p class=muted>Задач пока нет</p>'}function openTask(id){editing=id||null;const t=tasks.find(x=>x.id===id)||{};modal.classList.add('open');tTitle.value=t.title||'';tDesc.value=t.description||'';tFolder.value=t.folder_id||'';tUrgency.value=t.urgency||'not_urgent';tImportance.value=t.importance||'not_important';tStart.value=t.start_at||'';tDue.value=t.due_at||'';loadFiles()}function closeTask(){modal.classList.remove('open')}async function saveTask(){if(!tTitle.value.trim())return alert('Название обязательно');await fetch(api('/tasks'),{method:editing?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:editing,title:tTitle.value,description:tDesc.value,folder_id:tFolder.value,urgency:tUrgency.value,importance:tImportance.value,start_at:tStart.value,due_at:tDue.value})});closeTask();await load()}async function addFolder(){if(!folderName.value.trim())return;await fetch(api('/folders'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:folderName.value})});folderName.value='';await load()}async function loadFiles(){if(!editing){filesList.innerHTML='<p class=muted>Сначала сохраните задачу, потом прикрепляйте файлы.</p>';return}const files=await fetch(api('/files?task_id='+editing)).then(r=>r.json());filesList.innerHTML=files.map(f=>'<div class=row style="justify-content:space-between;background:white;border-radius:14px;padding:10px;margin:8px 0"><button class="btn ghost" onclick="previewFile('+f.id+',\''+f.file_type+'\')">'+f.file_name+'</button><span><a class="btn ghost" href="/zadachnik/api/files/'+f.id+'/download">Скачать</a> <button class="btn ghost" onclick="deleteFile('+f.id+')">Удалить</button></span></div>').join('')||'<p class=muted>Файлов пока нет</p>'}function previewFile(id,type){const url='/zadachnik/api/files/'+id+'/download';if((type||'').startsWith('image/')||type==='application/pdf')window.open(url,'_blank');else alert('Предпросмотр недоступен. Нажмите Скачать.')}async function uploadFile(){if(!editing)return alert('Сначала сохраните задачу');const f=fileInput.files[0];if(!f)return;const data=await new Promise(r=>{const reader=new FileReader();reader.onload=()=>r(reader.result.split(',')[1]);reader.readAsDataURL(f)});await fetch(api('/files'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({task_id:editing,file_name:f.name,file_type:f.type,data})});fileInput.value='';await loadFiles()}async function deleteFile(id){if(!confirm('Удалить файл?'))return;await fetch(api('/files/'+id),{method:'DELETE'});await loadFiles()}load();</script></body></html>`;
const body=req=>new Promise(r=>{let d='';req.on('data',c=>d+=c);req.on('end',()=>r(d?JSON.parse(d):{}))});
http.createServer(async(req,res)=>{try{if(req.url==='/zadachnik/'||req.url==='/zadachnik'){res.writeHead(200,{'Content-Type':'text/html; charset=utf-8'});return res.end(html)}if(req.url==='/zadachnik/api/folders'&&req.method==='GET'){res.writeHead(200,{'Content-Type':'application/json'});return res.end(sh('SELECT * FROM folders ORDER BY id DESC'))}if(req.url==='/zadachnik/api/folders'&&req.method==='POST'){const b=await body(req);run(`INSERT INTO folders(name) VALUES('${esc(b.name)}')`);res.writeHead(200);return res.end('{}')}if(req.url==='/zadachnik/api/tasks'&&req.method==='GET'){res.writeHead(200,{'Content-Type':'application/json'});return res.end(sh('SELECT tasks.*, folders.name AS folder_name FROM tasks LEFT JOIN folders ON folders.id=tasks.folder_id ORDER BY tasks.id DESC'))}if(req.url==='/zadachnik/api/tasks'&&req.method==='POST'){const b=await body(req);run(`INSERT INTO tasks(title,description,folder_id,urgency,importance,start_at,due_at,updated_at) VALUES('${esc(b.title)}','${esc(b.description)}',${b.folder_id?Number(b.folder_id):'NULL'},'${esc(b.urgency)}','${esc(b.importance)}','${esc(b.start_at)}','${esc(b.due_at)}',CURRENT_TIMESTAMP)`);res.writeHead(200);return res.end('{}')}if(req.url==='/zadachnik/api/tasks'&&req.method==='PUT'){const b=await body(req);run(`UPDATE tasks SET title='${esc(b.title)}',description='${esc(b.description)}',folder_id=${b.folder_id?Number(b.folder_id):'NULL'},urgency='${esc(b.urgency)}',importance='${esc(b.importance)}',start_at='${esc(b.start_at)}',due_at='${esc(b.due_at)}',updated_at=CURRENT_TIMESTAMP WHERE id=${Number(b.id)}`);res.writeHead(200);return res.end('{}')}if(req.url.startsWith('/zadachnik/api/files/')&&req.url.endsWith('/download')&&req.method==='GET'){const id=Number(req.url.split('/')[4]);const rows=JSON.parse(sh(`SELECT * FROM task_files WHERE id=${id}`));if(!rows[0]){res.writeHead(404);return res.end('Not found')}const f=rows[0];res.writeHead(200,{'Content-Type':f.file_type||'application/octet-stream','Content-Disposition':`inline; filename="${encodeURIComponent(f.file_name)}"`});return fs.createReadStream(f.file_path).pipe(res)}if(req.url.startsWith('/zadachnik/api/files/')&&req.method==='DELETE'){const id=Number(req.url.split('/')[4]);const rows=JSON.parse(sh(`SELECT * FROM task_files WHERE id=${id}`));if(rows[0]){try{fs.unlinkSync(rows[0].file_path)}catch{}run(`DELETE FROM task_files WHERE id=${id}`)}res.writeHead(200);return res.end('{}')}if(req.url.startsWith('/zadachnik/api/files?')&&req.method==='GET'){const u=new URL(req.url,'http://x');const task=Number(u.searchParams.get('task_id'));res.writeHead(200,{'Content-Type':'application/json'});return res.end(sh(`SELECT id,task_id,file_name,file_type,created_at FROM task_files WHERE task_id=${task} ORDER BY id DESC`))}if(req.url==='/zadachnik/api/files'&&req.method==='POST'){const b=await body(req);const safe=Date.now()+'_'+String(b.file_name||'file').replace(/[^a-zA-Z0-9а-яА-Я._-]/g,'_');const filePath=path.join(FILE_DIR,safe);fs.writeFileSync(filePath,Buffer.from(b.data,'base64'));run(`INSERT INTO task_files(task_id,file_name,file_type,file_path) VALUES(${Number(b.task_id)},'${esc(b.file_name)}','${esc(b.file_type)}','${esc(filePath)}')`);res.writeHead(200);return res.end('{}')}res.writeHead(404);res.end('Not found')}catch(e){res.writeHead(500,{'Content-Type':'text/plain'});res.end(String(e.stack||e))}}).listen(PORT,'127.0.0.1',()=>console.log('Zadachnik on '+PORT));
NODE
systemctl restart zadachnik.service
systemctl status zadachnik.service --no-pager
printf '\nГотово. Обнови страницу: http://80.74.30.154/zadachnik/\n'
